<?php
namespace Ishep\Services;use PDO;use Throwable;use DomainException;use Ishep\Repositories\{MemberDocumentRepository,MembershipApplicationRepository,AuditLogRepository,RoleRepository};
final class MemberDocumentService
{public function __construct(private PDO $db,private MemberDocumentRepository $documents,private MembershipApplicationRepository $applications,private PrivateDocumentStorage $storage,private AuditLogRepository $audits,private RoleRepository $roles,private DocumentStatus $statuses){}private function transaction(callable $f):mixed{$this->db->beginTransaction();try{$r=$f();$this->db->commit();return$r;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}private function reference():string{return'DOC-'.gmdate('Y').'-'.strtoupper(bin2hex(random_bytes(8)));}private function member(int $id):void{if(!in_array('registered_user',$this->roles->roles($id),true))throw new DomainException('Your account is not authorized to manage member documents.');}private function reviewer(int $id):void{if(!array_intersect($this->roles->roles($id),['administrator','super_user']))throw new DomainException('You are not authorized to verify documents.');}public function upload(int $uid,int $type,array $validated,string $ip,bool $http=true):array{$this->member($uid);$app=$this->applications->latestForUser($uid);if(!$app)throw new DomainException('Create a membership application before uploading documents.');if(!$this->documents->type($type))throw new DomainException('Select a valid active document type.');foreach($this->documents->currentForApplication((int)$app['id'])as$d)if((int)$d['document_type_id']===$type)throw new DomainException('Use Replace for an existing document of this type.');$stored=$this->storage->store($validated,$http);try{return$this->transaction(function()use($uid,$type,$validated,$stored,$app,$ip){$id=$this->documents->insert(['reference'=>$this->reference(),'user_id'=>$uid,'application_id'=>(int)$app['id'],'type_id'=>$type]+$validated+$stored);$this->documents->event($id,$uid,'uploaded',null,'pending','Document uploaded; malware scanning is not configured.');$this->audits->record($uid,'member_document.uploaded','member_document',$id,$ip);return$this->documents->currentForApplication((int)$app['id'])[0];});}catch(Throwable $e){$this->storage->remove($stored['relative_path']);throw$e;}}public function replace(int $uid,string $ref,array $validated,string $ip,bool $http=true):array{$this->member($uid);$old=$this->documents->byReference($ref);if(!$old||(int)$old['user_id']!==$uid)throw new DomainException('Document not found.');$this->statuses->assert($old['verification_status'],'replaced');$stored=$this->storage->store($validated,$http);try{return$this->transaction(function()use($uid,$old,$validated,$stored,$ip){$id=$this->documents->insert(['reference'=>$this->reference(),'user_id'=>$uid,'application_id'=>(int)$old['membership_application_id'],'type_id'=>(int)$old['document_type_id']]+$validated+$stored);$this->documents->transition((int)$old['id'],'replaced',$uid,null,null,$id);$this->documents->event((int)$old['id'],$uid,'replaced',$old['verification_status'],'replaced','A corrected replacement was uploaded.');$this->documents->event($id,$uid,'uploaded',null,'pending','Replacement document uploaded.');$this->audits->record($uid,'member_document.replaced','member_document',$id,$ip);return$this->documents->byReference($this->documents->currentForApplication((int)$old['membership_application_id'])[0]['document_reference']);});}catch(Throwable $e){$this->storage->remove($stored['relative_path']);throw$e;}}public function remove(int $uid,string $ref,string $ip):void{$this->member($uid);$d=$this->documents->byReference($ref);if(!$d||(int)$d['user_id']!==$uid)throw new DomainException('Document not found.');$this->statuses->assert($d['verification_status'],'removed');$this->transaction(function()use($uid,$d,$ip){$this->documents->transition((int)$d['id'],'removed',$uid);$this->documents->event((int)$d['id'],$uid,'removed',$d['verification_status'],'removed','Document removed from the active checklist.');$this->audits->record($uid,'member_document.removed','member_document',(int)$d['id'],$ip);});}public function review(string $ref,int $reviewer,string $to,string $reason,string $internal,string $ip):array{$this->reviewer($reviewer);$d=$this->documents->byReference($ref);if(!$d)throw new DomainException('Document not found.');$this->statuses->assert($d['verification_status'],$to);$reason=trim($reason);$internal=trim($internal);if($to==='rejected'&&$reason==='')throw new DomainException('An applicant-visible rejection reason is required.');if(mb_strlen($reason)>1000||mb_strlen($internal)>2000)throw new DomainException('Review notes exceed the allowed length.');return$this->transaction(function()use($d,$reviewer,$to,$reason,$internal,$ip){$this->documents->transition((int)$d['id'],$to,$reviewer,$reason?:null,$internal?:null);$this->documents->event((int)$d['id'],$reviewer,$to,$d['verification_status'],$to,$to==='rejected'?$reason:'Document verified.');$this->audits->record($reviewer,'member_document.'.$to,'member_document',(int)$d['id'],$ip);return$this->documents->byReference($d['document_reference']);});}}
